/dt;let gForce=accelMag/9.81;let lagFactor=0.1;if(gForce>2){lagFactor=0.02;highGTimer=30;}letLag=highGTimer>0?0.02:0.1;display.speed=lerp(display.speed,speed,displayLag);if(!altStuck||altStuckTimer<=0){let targetAlt=aircraft.z;let diff=Math.abs(targetAlt-Math.round(targetAlt/1000)*1000);if(diff<5){altStuck=true;altStuckTimer=30;}display.altitude=lerp(display.altitude,targetAlt,displayLag);}else{altStuckTimer--;if(altStuckTimer<=0)Stuck=false;}let heading=toDeg(aircraft.yaw)%360;if(heading<0)heading+=360;if(aircraft.x>2000&&aircraft.x<3000){heading+=15*Math.sin(performance.now()/500);display.heading=lerp(display.heading,heading,0.05);}else{display.heading=lerp(display.heading,heading,displayLag);}display.fuel=lerp(display.fuel,aircraft.fuel,displayLag);if(highGTimer>0)highGTimer--;}function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);const horizonY=canvas.height/2+aircraft.pitch*2;ctx.fillStyle='#87CEEB';ctx.fillRect(0,0,canvas.width,horizonY);ctx.fillStyle='#228B22';ctx.fillRect(0,horizonY,canvas.width,canvas.height-horizonY);ctx.strokeStyle='#FFFFFFctx.beginPath();ctx.moveTo0,horizonY);ctx.lineTo(canvas.width,horizonY);ctx.stroke();ctx.fillStyle='rgba(139,69,19,0.5)';for(let i=-5;i<5;i++){let sx=canvas.width/2+aircraft.roll*5+i*50;let sy=horizonY+Math.tan(toRad(aircraft.pitch))*i*30;ctx.beginPath();ctx.arc(sx,sy,30,0,2*Math.PI);ctx.fill();}ctx.fillStyle='#000';ctx.font='14px monospace';ctx.textAlign='left';ctx.fillText('SPD: '+display.speed.toFixed(1)+' m/s',10,20);ctx.fillText('ALT: '+display.altitude.toFixed(0)+' m',10,40);ctx.fillText('HDG: '+display.heading.toFixed(0)+'°',10,60);ctx.fillText('FUEL: '+display.fuel.toFixed(0)+' L',10,80);if(highGTimer>0){ctx.fillStyle='red';ctx.fillText('HIGH G-LAG',10,100);}if(altStuck){ctx.fillStyle='orange';ctx.fillText('ALT STICKY',10,120);}if(aircraft.x>2000&&aircraft.x<3000){ctx.fillStyle='orange';ctx.fillText('COMPASS ANOMALY',10,140);}if(Math.abs(aircraft.pitch)>15){ctx.fillStyle='orange';ctx.fillText('ENGINE FLU